// Kalkulator Barn & Silo (jadi tab di index.html)
var IMG={"bolts": "data:image/webp;base64,", "ducttape": "data:image/webp;base64,", "planks": "data:image/webp;base64,", "nails": "data:image/webp;base64,", "woodpanels": "data:image/webp;base64,", "screws": "data:image/webp;base64,", "barn": "data:image/webp;base64,", "silo": "data:image/webp;base64,"};
(function(){
  var TYPES={
    barn:{label:"Barn",mats:[["Bolts","bolts"],["Planks","planks"],["Duct Tape","ducttape"]]},
    silo:{label:"Silo",mats:[["Nails","nails"],["Wood Panels","woodpanels"],["Screws","screws"]]}
  };
  var type="barn", have={}, per={};
  var cur=document.getElementById("calcCur"), tgt=document.getElementById("calcTgt");
  var err=document.getElementById("calcErr"), res=document.getElementById("calcResult");

  function levelOf(c){
    if(!isFinite(c)||c<50) return null;
    if(c<=1000) return (c-50)%25===0 ? (c-50)/25+1 : null;
    return (c-1000)%50===0 ? 39+(c-1000)/50 : null;
  }
  function fmt(n){return n.toLocaleString("id-ID");}

  function perOf(k,i){return per[k]!=null?per[k]:(i===0?29:30);}
  function renderDays(m,each){
    var maxD=0;
    m.forEach(function(it,i){
      var k=type+":"+it[0], h=have[k]==null?0:have[k], p=perOf(k,i);
      var d=Math.ceil(Math.max(0,each-h)/p);
      if(d>maxD) maxD=d;
    });
    var html="<h2 class='calc-h2'>Estimasi waktu</h2>"+
      "<div class='calc-big'>"+(maxD===0?"Material sudah cukup":"±"+fmt(maxD)+" hari")+"</div>";
    if(maxD>0){
      html+="<button type='button' class='calc-order-btn' data-days='"+maxD+"'>🛒 Pesan Sekarang — Paket "+fmt(maxD)+" Hari</button>";
    }
    document.getElementById("calcDays").innerHTML=html;
  }
  function render(){
    var hero=document.getElementById("calcHero");
    hero.src=IMG[type]; hero.alt=TYPES[type].label;
    var a=levelOf(parseInt(cur.value,10)), b=levelOf(parseInt(tgt.value,10));
    if(a===null||b===null){
      err.textContent="Kapasitas tidak valid. Contoh: 50, 75, 100 … 1000, 1050, 1100.";
      res.hidden=true; return;
    }
    if(b<=a){
      err.textContent="Target harus lebih besar dari kapasitas sekarang.";
      res.hidden=true; return;
    }
    err.textContent="";
    var each=(a+b-1)*(b-a)/2;
    document.getElementById("calcLv").textContent="Lv "+a+" → Lv "+b;
    document.getElementById("calcUps").textContent=fmt(b-a)+"x";
    var m=TYPES[type].mats, html="";
    m.forEach(function(it){
      var name=it[0], k=type+":"+name, h=have[k]==null?"":have[k];
      var diff=(h===""?0:h)-each;
      var txt=h===""?"-":(diff>=0?"+"+fmt(diff):fmt(diff));
      var cls=h===""?"":(diff>=0?"ok":"bad");
      html+="<tr><td><div class='calc-mat'><img src='"+IMG[it[1]]+"' alt=''><span>"+name+"</span></div></td><td class='calc-n'>"+fmt(each)+"</td>"+
        "<td class='calc-n'><input type='number' min='0' inputmode='numeric' data-k='"+k+"' value='"+h+"' aria-label='Punya "+name+"'></td>"+
        "<td class='calc-n calc-short "+cls+"'>"+txt+"</td></tr>";
    });
    document.getElementById("calcMats").innerHTML=html;
    renderDays(m,each);
    document.getElementById("calcTotal").textContent="Total semua material: "+fmt(each*3)+" buah ("+fmt(each)+" tiap jenis).";
    res.hidden=false;
  }

  document.getElementById("calcMats").addEventListener("change",function(e){
    var k=e.target.getAttribute&&e.target.getAttribute("data-k");
    if(!k) return;
    var v=parseInt(e.target.value,10);
    have[k]=isNaN(v)||v<0?null:v;
    render();
  });
  // Tombol "Pesan Sekarang": buka form order Barn Item / Silo Item, jumlah set = jumlah hari
  document.getElementById("calcDays").addEventListener("click",function(e){
    var btn=e.target.closest&&e.target.closest(".calc-order-btn");
    if(!btn) return;
    var days=parseInt(btn.getAttribute("data-days"),10);
    if(!days||typeof openBulkItemForm!=="function") return;
    openBulkItemForm(type==="barn"?"Barn Item":"Silo Item");
    document.getElementById("bulkItemQty").value=days;
    updateBulkItemPreview();
  });
  cur.addEventListener("input",render);
  tgt.addEventListener("input",render);

  function setType(t){
    type=t;
    document.getElementById("calcTabBarn").setAttribute("aria-selected",t==="barn");
    document.getElementById("calcTabSilo").setAttribute("aria-selected",t==="silo");
    render();
  }
  document.getElementById("calcTabBarn").onclick=function(){setType("barn")};
  document.getElementById("calcTabSilo").onclick=function(){setType("silo")};
  render();
})();
